/* --- 通用输入框提示词自定义 ，源自墨千尾，感谢老师/(ㄒoㄒ)/~~--- */

#nonQRFormItems {
    position: relative;
}

#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; /* 移除可能存在的文字阴影 */
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "⋆₊ ⊹˚不管多少时间我会等你⋆｡₊"; /*☁️自定义文本*/
    position: absolute; /* 使用绝对定位，让它能自由移动 */
    top: 50%; 
    left: 50%;
    transform: translate(-50%, -50%); /* 精确居中 */

    font-style: oblique; /* 字体样式：可以改为 normal (正常) 或 oblique (倾斜) */
    font-size: 0.5em;  
    pointer-events: none; 
    z-index: 10; /* 确保它显示在最上层 */

    white-space: nowrap; 
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px); /* 限制最大宽度，防止溢出输入框 */
}

/* ===== 气泡、图片宽度修改 ===== */
body.bubblechat .mes, body.bubblechat .mes[is_user="true"] {
    padding: 13px;
    border-radius: 0 0 15px 15px;
    padding-bottom: 30px;
    border: none;
    max-width: 360px;/*💌*/
    margin: 200px auto 15px auto;
    position: relative;
    background-color: rgb(255 255 255 / 90%) ;
}

.mes {
    padding: 13px;
    border-radius: 0 0 15px 15px;
    padding-bottom: 30px;
    border: none;
    max-width: 360px;/*💌*/
    margin: 200px auto 15px auto;
    position: relative;
    background-color: rgb(255 255 255 / 90%) ;
}

.mesAvatarWrapper {
    width: 360px;/*💌*/
    height: 200px;
    object-fit: cover;
    display: block;
    position: absolute;
    left: 50%;
