/* ===== 字体 ===== */
@font-face {
    font-family: "Jing Hua ";
    src: url("https://files.catbox.moe/138mza.ttf") format("truetype");
}
body, #nonQRFormItems textarea,.mes_text pre code, .mes_reasoning pre code,input, select, button {
    font-family: "Jing Hua ", sans-serif;
    font-size:18px;
    line-height:1.6
}

code {
    background-color: rgb(193 193 193 / 20%);
    color: rgb(99 99 99);
}

/* 斜体 */
.mes_text em {
    text-decoration: underline;
    text-decoration-color: #8d8d8dc2;
    text-decoration-thickness: 2px;
}
/* 引用 */
.mes_text q {
    background: linear-gradient(135deg, rgb(148 148 148 / 30%), rgb(148 146 146 / 0%));
    padding: 0px 0px;
    display: inline;
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
}
/* 代码块 */
.mes_text pre, .mes_reasoning pre {
    background-color: #282828;
    padding: 5px 5px 25px;
    border-radius: 5PX;
    margin: 15px 0 10px;
    position: relative;
    box-sizing: border-box;
}


.mes_text pre code, .mes_reasoning pre code {
    background-color: #efefef;
    color: #3b3b3b;
    box-sizing: border-box;
    border-radius: 5px;
}

#chat > div > div.mes_block > div.mes_text > pre > code > i {
  font-size: 0; /* 隐藏原图标内容 */
  display: inline-block;
  width: 20px;
  height: 20px;
  background: url('https://i.postimg.cc/gjSWzyN2/IMG-2726.png') no-repeat center;
  background-size: contain;
  vertical-align: middle;
  margin:0;
}

/*引用块*/
.mes_text blockquote, .mes_reasoning blockquote {
    background-color: rgb(161 153 143 / 10%);
    border-radius: 5px;
}
/* ===== 动画 ===== */
/* 移除原始伪元素 */
#load-spinner ,#load-spinner::before{
   animation: none;
   content: "";
}

/* 创建新的自定义加载动画 */
#load-spinner::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 60px;
    height: 60px;
    background: url('https://i.postimg.cc/mgPpcV1z/IMG-2725.png') center/contain no-repeat;
    transform: translate(-50%, -50%);
    z-index: 1000;

}


/* 隐藏原有旋转动画 */
@keyframes custom-spin {
    display: none;
}
/* ===== 思维块美化 ===== */
.mes_reasoning_header {
    cursor: pointer;
    position: relative;
    left: 50%;
    transform: translate(-50%, -50%);
    user-select: none;
    margin: 5px;
    padding: 2px 8px;
    padding-right: calc(0.7em + 14px);
    background-color: #ffffff38;
    border: 2px dashed #9a9a9a;
    border-radius: 20px;
    font-size: calc(var(--mainFontSize) * 0.9);
    color: #868686;
    align-items: baseline;
    font-size: 0 !important;
}


.fa-chevron-up:before {
    content: ""; /* 去除原有样式 */
}

.fa-chevron-up::before {
    content: "";
    display: inline-block;
    width: 10px;
    height: 10px;
    background-image: url("https://i.postimg.cc/4NmzmGZS/IMG-2480.png");
    background-size: 10px 10px;
    background-repeat: no-repeat;
}

/* ====== 气泡 ====== */


.mes_block {
    padding-left: 0;
}

/* 翻页 */
.swipe_left {
    left: 5px;
}

/* 文本 */
.mes_text {
    padding-left: 5px;
    padding-top: 5px;
    padding-bottom: 5px;
    padding-right: 5px;
}

.reasoning_edit_textarea, .edit_textarea {
    background-color: rgb(187 187 187 / 23%);
}
/* ====== 头像 ====== */


.mes .mes_timer {
    cursor: default;
    opacity: 0.7;
    font-size: 0.65em;
    font-weight: normal;
    text-align: right;
    position: absolute;
    left: calc(50% + 30px); /* 中心向左偏移150px */
    top: 170px;    
    white-space: nowrap; /* 防止换行 */
    z-index: 10;
    background-color: rgb(197 197 197 / 70%);
    border-radius: 3px;
}
.mes .mes_timer::before {
    content: "已听";
    display: inline;
}


.mes .mesIDDisplay {
    cursor: default;
    opacity: 0.7;
    font-size: 0.65em;
    font-weight: normal;
    text-align: right;
    position: absolute;
    white-space: nowrap; /* 防止换行 */
    right: calc(50% + 30px); /* 中心向左偏移150px */
    top: 170px;    
    z-index: 10;
    background-color: rgb(197 197 197 / 70%);
    border-radius: 3px;
}
.mes .mesIDDisplay::after {
    content: " 关注";
    display: inline;
}

.mes .tokenCounterDisplay {
    cursor: default;
  left: 50%;
  transform: translateX(-50%);
    opacity: 0.7;
    font-size: 0.65em;
    font-weight: normal;
    text-align: right;
    position: absolute;
    text-align: right; /* 右对齐 */
    white-space: nowrap; /* 防止换行 */
    top: 170px;
    z-index: 10;
    background-color: rgb(197 197 197 / 70%);
    border-radius: 3px;
}
.mes .tokenCounterDisplay::after {
    content: " 粉丝";
    display: inline;
}


/* 时间戳位置 */
.mes .timestamp {
    font-size: 0.5em;
    font-weight: normal;
    position: absolute;
  left: 50%;
  transform: translateX(-50%);
    top: 3px;
    text-align: right;
    white-space: nowrap;
    z-index: 10;
    opacity: 0.7;
}

.mes .name_text {
    font-size: 1em;
    position: absolute; /* 绝对定位 */
  left: 50%;
  transform: translateX(-50%);
    top: -50px; /* Y轴向上偏移165px */
    text-align: center; 
    white-space: nowrap; /* 防止换行 */
    z-index: 10; /* 确保显示在最前面 */
    cursor: default;
    opacity: 1;
    font-weight: normal;
}

.mes_block {
  transform: none !important;
}

/* ===== 底部输入栏 ===== */

#send_form {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    width: 100%;
    margin: 0px auto 0px auto; /* 上下边距15px */
    border-radius: 10px;
}

#nonQRFormItems {
    padding: 1px;
    border: 0;
    position: relative;
    background-position: center;
    display: flex;
    flex-direction: row;
    column-gap: 5px;
    order: 25;
    width: 100%;
    min-height: 30px;
    align-items: center;
    overflow: hidden;
    border-radius: 10px;
}

#rightSendForm>div:not(.mes_stop), #leftSendForm>div{
    transform: scale(0.7);
    color:#000000;
}
/* ===== 顶部 ===== */

#top-bar {
    margin:0 auto;
    left: 0;
    right: 0;
    display: inline-block;
    height: 30px; /* 固定高度 */
    position: absolute;
    box-shadow: none;
    opacity:0;
    z-index: 3005;
}

.drawer-icon {
    transform: scale(0.7);
    color:#000000;
}

/* ===== UI ===== */
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader {
    background: -webkit-linear-gradient(right, #c1c1c100, #b9b9b9);
    opacity: 0.7;
    margin-bottom: 4px;
    padding: 2px 5px 2px 5px;
    border: 2px solid rgb(153 153 153);
    position: relative;
    border-radius: 0px;
    box-shadow: none !important;
}

/* 滑块 */

input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    margin: 0;
    padding: 0;
    width: 100%;
    height: 5px;
    background: var(--white50a);
    border-radius: 15px;
    background-size: 70% 100%;
    background-repeat: no-repeat;
    cursor: ew-resize;
    /* 移除可能的阴影 */
    box-shadow: none;
}

/* Webkit浏览器滑块样式 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 30px;
    height: 30px;
    background: url('https://i.postimg.cc/mgPpcV1z/IMG-2725.png') center/contain no-repeat;
    cursor: pointer;
    border: none;
    /* 移除滑块阴影 */
    box-shadow: none;
}

/* Firefox浏览器滑块样式 */
input[type="range"]::-moz-range-thumb {
    width: 30px;
    height: 30px;
    background: url('https://i.postimg.cc/mgPpcV1z/IMG-2725.png') center/contain no-repeat;
    cursor: pointer;
    border: none;
    /* 移除滑块阴影 */
    box-shadow: none;
}

/* 针对IE浏览器（如果需要） */
input[type="range"]::-ms-thumb {
    box-shadow: none;
}

/* 图标 */

.fa-bars:before, .fa-navicon:before {
    width: 20px;
    height: 20px;
}

.fa-magic-wand-sparkles:before, .fa-wand-magic-sparkles:before {
    width: 20px;
    height: 20px;
}

.drawer-content select {
    background-color: #bbbbbb2b;
    border-radius: 3px;
}

.neo-range-input, #completion_prompt_manager #completion_prompt_manager_list {
    background-color: #c9c9c924;
}

textarea, .textarea_compact, .range-block-counter input, .text_pole {
    background-color: #e6e6e6;
    color: rgb(134 133 133);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: #b7b7b7;
}

#completion_prompt_manager .completion_prompt_manager_header div {
    color: #918a86;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter:none;
}

/*预设正则空间预留*/
#global_scripts_block ,#scoped_scripts_block ,#completion_prompt_manager_list{
    padding-right: 30px;
}

/*热切换*/
#HotSwapWrapper {
    position: relative;
    overflow-x: auto;
    scrollbar-width: thin; /* Firefox */
    scrollbar-color: rgba(255, 182, 193, 0.3) 
}

#HotSwapWrapper::-webkit-scrollbar {
    height: 1px; /* 设置滚动条高度为3px */
}

#HotSwapWrapper::-webkit-scrollbar-track {
    background: transparent; /* 滚动条轨道透明 */
}

#HotSwapWrapper::-webkit-scrollbar-thumb {
    scrollbar-color: rgba(255, 182, 193, 0.3) 
    border-radius: 0; /* 无圆角 */
    border: none; /* 无边框 */
}

#HotSwapWrapper > * {
    flex-shrink: 0;
}



/* --- 默认隐藏 QR 按钮容器，并设置平滑过渡 --- */
.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.5s ease,
    transform 0.5s ease;
}

/* --- 输入框获得焦点时显示 QR 区域 --- */
#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 45px;
  transform: translateY(0);
  pointer-events: auto;
}

/* --- 新增：修复空白弹窗，仅隐藏空白背景，不影响点击 --- */
#qr--bar {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.3s ease;
}

/* --- 当输入框聚焦或激活时才显示 QR bar 内容 --- */
#send_form:focus-within #qr--bar,
.qr--buttons.active #qr--bar {
  opacity: 1;
  visibility: visible;
  max-height: 45px;
  pointer-events: auto;
}



/* 全局滑动条样式 */
::-webkit-scrollbar {
    width: 1px; /* 滑动条宽度 */
    height: 1px; /* 水平滑动条高度 */
}

::-webkit-scrollbar-track {
    background: transparent; /* 轨道背景透明 */
}

::-webkit-scrollbar-thumb {
    background: rgba(197,197, 197, 0.5); /* 半透明浅粉色 */
    border-radius: 0; /* 无圆角 */
}

::-webkit-scrollbar-thumb:hover {
    background: rgba(197,197, 197, 0.5); /* 鼠标悬停时稍微加深 */
}

/* Firefox 浏览器 */
* {
    scrollbar-width: thin; /* 细滚动条 */
    scrollbar-color: rgba(197,197, 197, 0.5) transparent; /* 滑块半透明浅粉色，轨道透明 */
}


/* 分割线 */


hr {
    background-image: url("https://i.postimg.cc/GhHL3j5s/IMG-2728.png") !important;
    background-size: 250px 25px !important;
    background-repeat: repeat !important;
    margin: 5px 0 !important;
    height: 20px !important;
    min-height: 25px !important;
    border: 0 !important;
    opacity: 0.8 !important;
    display: block !important;
    visibility: visible !important;
}

body.bubblechat .welcomePanel {
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    background-color: rgb(247 247 247 / 70%);
}

.select2-container .select2-selection--multiple, .select2-container .select2-selection--single {
    background-color: rgb(0 0 0 / 0%);
}

.select_chat_block[highlight] {
    background-color: rgb(167 167 167 / 30%);
}

.reverse_proxy_warning:not(small) {
    background-color: rgb(207 207 207 / 70%);
    color: rgb(43 42 42 / 90%);
}
